const queryTypes = yield* Database.resolve('dxn:org.dxos.operation.discovery.queryTypes');
const t = yield* Operation.invoke(queryTypes, { typenames: ['com.example.type.task'] });
yield* print('types', t);
const loadSkill = yield* Database.resolve('dxn:org.dxos.operation.discovery.loadSkill');
const skills = yield* Operation.invoke(loadSkill, {});
yield* print('skills', skills);
const queryOps = yield* Database.resolve('dxn:org.dxos.operation.discovery.queryOperations');
const ops = yield* Operation.invoke(queryOps, { query: 'score task priority' });
yield* print('ops', ops);

